import { CommonModule, isPlatformBrowser } from '@angular/common';
import { Component, OnInit, ChangeDetectorRef, ChangeDetectionStrategy, Inject, DOCUMENT, PLATFORM_ID } from '@angular/core';
import { RouterModule } from '@angular/router';
import { LucideAngularModule } from 'lucide-angular';

import { BannerService } from '../../core/banner/banner.service';
import { BannerComponent } from '../../components/banner/banner.component';
import { environment } from '../../../environments/environment';
import { TranslationService } from '../../core/services/translation.service';
import { TestimonialService } from '../../providers/testimonial/testimonial.service';
import { TestimonialsComponent } from '../../shared/testimonials/testimonials.component';
import { FaqComponent } from "../../shared/faq/faq.component";
import { FaqService } from '../../core/faq/faq.service';
import { TranslateModule } from '@ngx-translate/core';
import { PageSchemaService } from '../../core/services/page-schema.service';
@Component({
  selector: 'app-about',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    CommonModule,
    RouterModule,
    LucideAngularModule,
    BannerComponent,
    FaqComponent,
    TestimonialsComponent,
    TranslateModule
  ],
  templateUrl: './about.component.html',
  styleUrl: './about.component.scss'
})
export class AboutComponent implements OnInit {
  bannerData: any[] = [];
  baseUrl: any;
  hasBanner: boolean = false;
  homeTestimonials: any[] = [];
  generalFaqs: { question: string; answer: string }[] = [];
  constructor(
    private bannerService: BannerService,
    private cdr: ChangeDetectorRef,
    private testimonialService: TestimonialService,
    public translationService: TranslationService,
    @Inject(DOCUMENT) private document: Document,
    @Inject(PLATFORM_ID) private platformId: Object,
    private faqService: FaqService,
    private pageSchemaService: PageSchemaService,
  ) {
    this.baseUrl = environment.url;
  }
  ngOnInit(): void {
    this.getBannerdata();
    if (!isPlatformBrowser(this.platformId)) {
      this.loadSecondaryContent();
      return;
    }

    if ('requestIdleCallback' in globalThis) {
      globalThis.requestIdleCallback(() => {
        this.loadSecondaryContent();
      });
      return;
    }

    setTimeout(() => {
      this.loadSecondaryContent();
    }, 1000);
  }
  loadSecondaryContent() {
    this.getFaqsData();
    this.getTestimonialsData();

    this.addSchema();
    this.addAboutPageSchema();
    this.addBreadcrumbSchema();
    this.addDynamicSchema();
  }
  // Module 10 redesign — renders any agent-applied JSON-LD blocks (AboutPage,
  // CollectionPage, etc.) from PageSchema/Mongo, alongside the hardcoded blocks
  // above. See PageSchemaService for how these reach the live page without a
  // frontend deploy.
  addDynamicSchema() {
    this.pageSchemaService.getPageSchema('about').subscribe((blocks) => {
      for (const block of blocks) {
        const existing = this.document.getElementById(`schema-agent-${block.schemaType}`);
        if (existing) existing.remove();
        const script = this.document.createElement('script');
        script.type = 'application/ld+json';
        script.id = `schema-agent-${block.schemaType}`;
        script.textContent = block.jsonLd;
        this.document.head.appendChild(script);
      }
    });
  }
  getBannerdata() {
    const obj = {
      userUrl: '/projects',
      btnContent: 'Explore Our Projects',
      btnContent_ar: 'استكشف مشاريعنا'
    };

    this.bannerService.getHomeBanner(obj).subscribe({
      next: (response: any) => {
        if (response?.code === 200 && response?.result?.length > 0) {
          this.bannerData = response.result
            .filter((item: any) => item.page === 'about-page')
            .map((item: any) => ({
              ...item,
              userUrl: obj.userUrl,
              btnContent: obj.btnContent,
              btnContent_ar: obj.btnContent_ar
            }));

          this.hasBanner = this.bannerData.length > 0;
          this.cdr.markForCheck();
        }
      },
      error: (err) => {
        console.error('Banner API error:', err);
      }
    });
  }
  getTestimonialsData() {
    this.testimonialService.getAlltestimonial({}).subscribe((res: any) => {
      if (res.code == 200) {
        this.homeTestimonials = res?.result;
        this.cdr.markForCheck();
      }
    })
  }
  getFaqsData() {
    const obj = {
      type: 'General'
    }
    this.faqService.getFaqs(obj).subscribe((res: any) => {
      if (res.code == 200) {
        this.generalFaqs = res?.result;
        this.addFaqSchema();
        this.cdr.markForCheck();
      }
    })
  }
  addSchema() {
    const script = this.document.createElement('script');
    script.type = 'application/ld+json';
    script.id = 'about-webpage-schema';
    script.textContent = JSON.stringify({
      "@context": "https://schema.org",
      "@type": "WebPage",
      "name": "About",
      "description": "About Pixtar - Premium branding and website design agency in Dubai-UAE",
      "url": "https://www.pixtar.ae/about"
    });

    this.document.head.appendChild(script);
  }

  addAboutPageSchema() {
    const existingScript = this.document.getElementById('about-page-schema');
    if (existingScript) return;

    const script = this.document.createElement('script');
    script.type = 'application/ld+json';
    script.id = 'about-page-schema';
    script.textContent = JSON.stringify({
      "@context": "https://schema.org",
      "@type": "AboutPage",
      "name": "About Pixtar",
      "description": "Learn about Pixtar, a premium branding and website design agency based in Dubai, UAE. Specializing in creative branding, custom websites, ecommerce solutions, and graphic design.",
      "url": "https://www.pixtar.ae/about",
      "image": "https://www.pixtar.ae/images/logo/pixtar-main-logo.webp",
      "publisher": {
        "@type": "Organization",
        "@id": "https://www.pixtar.ae/#organization"
      }
    });

    this.document.head.appendChild(script);
  }
  addBreadcrumbSchema() {
    const existingScript = this.document.getElementById('breadcrumb-schema-about');
    if (existingScript) return;

    const script = this.document.createElement('script');
    script.type = 'application/ld+json';
    script.id = 'breadcrumb-schema-about';

    script.textContent = JSON.stringify({
      "@context": "https://schema.org",
      "@type": "BreadcrumbList",
      "itemListElement": [
        {
          "@type": "ListItem",
          "position": 1,
          "name": "Home",
          "item": "https://www.pixtar.ae/"
        },
        {
          "@type": "ListItem",
          "position": 2,
          "name": "About",
          "item": "https://www.pixtar.ae/about"
        }
      ]
    });

    this.document.head.appendChild(script);
  }
  addFaqSchema() {
    if (!this.generalFaqs || this.generalFaqs.length === 0) return;

    const existingScript = this.document.getElementById('faq-schema-about');
    if (existingScript) {
      existingScript.remove();
    }

    const faqSchema = {
      "@context": "https://schema.org",
      "@type": "FAQPage",
      "mainEntity": this.generalFaqs.map((faq: any) => ({
        "@type": "Question",
        "name": faq.question,
        "acceptedAnswer": {
          "@type": "Answer",
          "text": faq.answer
        }
      }))
    };

    const script = this.document.createElement('script');
    script.type = 'application/ld+json';
    script.id = 'faq-schema-about';
    script.textContent = JSON.stringify(faqSchema);

    this.document.head.appendChild(script);
  }
}
